using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AltarOfFractalsButtonCustomEventSetup", menuName = "Data/BattleSceneSetups/Events/AltarOfFractalsButtonCustomEventSetup", order = 0)]
public class AltarOfFractalsButtonCustomEventSetup : ButtonCustomEventSetup
{
	private const string altarOfFractalsDiceDuplicatedDescriptionID = "AltarOfFractalsDiceDuplicatedDescription";

	protected override void InitializeSpineAnimation(EventSpritesSkeleton eventSpritesSkeleton)
	{
		string animationName = "Idle" + ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		eventSpritesSkeleton.SkeletonGraphic.AnimationState.SetAnimation(0, animationName, loop: true);
	}

	public override string GetButtonPressedEventDescription(int buttonIndex)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("AltarOfFractalsDiceDuplicatedDescription"), base.GetButtonPressedEventDescription(buttonIndex));
	}
}
